SELECT * FROM settlement_processing_record


        AND process_type = #{processType}


        AND process_status = #{processStatus}


        AND batch_no = #{batchNo}


        AND DATE(create_time) >= #{startDate}


        AND DATE(create_time) <= #{endDate}


        AND org_id = #{orgId}


ORDER BY create_time DESC

SELECT * FROM settlement_processing_record
WHERE pending_id = #{pendingId}
ORDER BY create_time DESC

SELECT * FROM settlement_processing_record
WHERE batch_no = #{batchNo} AND org_id = #{orgId}
ORDER BY create_time DESC

SELECT * FROM settlement_processing_record
WHERE process_status = #{processStatus} AND org_id = #{orgId}
ORDER BY create_time DESC

SELECT * FROM settlement_processing_record
WHERE process_status = 'FAILED'
AND retry_count < max_retry_count
AND next_retry_time <= #{currentTime}
AND org_id = #{orgId}
ORDER BY next_retry_time ASC

SELECT COUNT(*) as totalCount, SUM(CASE WHEN process_status = 'PENDING' THEN 1 ELSE 0 END) as pendingCount, SUM(CASE WHEN process_status = 'PROCESSING' THEN 1 ELSE 0 END) as processingCount, SUM(CASE WHEN process_status = 'SUCCESS' THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN process_status = 'FAILED' THEN 1 ELSE 0 END) as failedCount, SUM(CASE WHEN process_status = 'TIMEOUT' THEN 1 ELSE 0 END) as timeoutCount, AVG(processing_duration) as avgDuration, MAX(processing_duration) as maxDuration, MIN(processing_duration) as minDuration FROM settlement_processing_record WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}

SELECT process_type, COUNT(*) as count, SUM(CASE WHEN process_status = 'SUCCESS' THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN process_status = 'FAILED' THEN 1 ELSE 0 END) as failedCount, AVG(processing_duration) as avgDuration FROM settlement_processing_record WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY process_type ORDER BY count DESC

SELECT batch_no, COUNT(*) as count, SUM(CASE WHEN process_status = 'SUCCESS' THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN process_status = 'FAILED' THEN 1 ELSE 0 END) as failedCount, AVG(processing_duration) as avgDuration, MIN(start_time) as batchStartTime, MAX(end_time) as batchEndTime FROM settlement_processing_record WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY batch_no ORDER BY batchStartTime DESC

SELECT error_code, error_message, COUNT(*) as count, MAX(create_time) as lastOccurrence FROM settlement_processing_record WHERE process_status = 'FAILED' AND org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY error_code, error_message ORDER BY count DESC

SELECT retry_count, COUNT(*) as count, SUM(CASE WHEN process_status = 'SUCCESS' THEN 1 ELSE 0 END) as finalSuccessCount FROM settlement_processing_record WHERE retry_count > 0 AND org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY retry_count ORDER BY retry_count
